// Version A
function processOrder(items: LineItem[], discountRate: number) {
  const itemTotals = calculateItemTotals(items);
  const discounted = applyDiscount(itemTotals, discountRate);
  saveOrder({ items, total: discounted });
}
function calculateItemTotals(items: LineItem[]) {
  return items.reduce((s, i) => s + i.price * i.quantity, 0);
}
function applyDiscount(total: number, rate: number) {
  return total * (1 - rate);
}

// Version B
function processOrder(items: LineItem[], discountRate: number) {
  let total = 0;
  for (const i of items) { total += i.price * i.quantity; }
  const apply = () => { total = total * (1 - discountRate); };
  apply();
  saveOrder({ items, total });
}
